inline const StaffAction* staff_action(std::string_view id) {
    const auto& actions=staff_actions();const auto it=std::ranges::find_if(actions,[&](const auto& a){return a.id==id;});
    return it==actions.end()?nullptr:&*it;
}
inline std::string staff_permission(const StaffAction& a) {return a.prefix.substr(0,a.prefix.find(' '));}
